package com.zoro.zoromart.service;
import com.zoro.zoromart.dao.MarketplaceDAO;import com.zoro.zoromart.dao.ProductDAO;import com.zoro.zoromart.util.ValidationUtil;import java.sql.SQLException;import java.util.List;import java.util.Map;
/** Applies cart quantity and stock rules before delegating cart persistence. */
public class CartService {private final MarketplaceDAO cart;private final ProductDAO products;public CartService(MarketplaceDAO cart,ProductDAO products){this.cart=cart;this.products=products;}public List<Map<String,Object>> get(long userId)throws SQLException{return cart.cart(userId);}public void add(long userId,long productId,int requestedQuantity)throws SQLException{int quantity=ValidationUtil.quantity(requestedQuantity);Map<String,Object> product=products.get(productId);if(product==null)throw new IllegalArgumentException("Product not found");int stock=((Number)product.get("stockQty")).intValue();int current=0;for(Map<String,Object> item:cart.cart(userId)){if(((Number)item.get("productId")).longValue()==productId)current=((Number)item.get("quantity")).intValue();}if(current+quantity>stock)throw new IllegalArgumentException("Requested quantity exceeds available stock");cart.addCart(userId,productId,quantity);}public boolean update(long userId,long cartItemId,int requestedQuantity)throws SQLException{int quantity=ValidationUtil.quantity(requestedQuantity);for(Map<String,Object> item:cart.cart(userId)){if(((Number)item.get("id")).longValue()==cartItemId){if(quantity>((Number)item.get("stockQty")).intValue())throw new IllegalArgumentException("Quantity exceeds available stock");return cart.updateCart(userId,cartItemId,quantity);}}return false;}public boolean remove(long userId,long cartItemId)throws SQLException{return cart.removeCart(userId,cartItemId);}}
